"""Parcel records."""


class Parcel:
    def __init__(self, depot, grams):
        self.depot = depot
        self.grams = grams

    def __repr__(self):
        return "Parcel(%r, %r)" % (self.depot, self.grams)


ROWS = [('bath', 34), ('york', 46), ('hull', 42), ('york', 23), ('york', 59), ('leeds', 6), ('leeds', 32)]


def load_parcels():
    """Yield the stored parcels one at a time."""
    for depot, grams in ROWS:
        yield Parcel(depot, grams)


def feed_parcels():
    """Endless feed of parcels: repeats the stored rows for ever."""
    while True:
        for depot, grams in ROWS:
            yield Parcel(depot, grams)
